package com.chipprbots.fukuii.crypto

import org.bouncycastle.util.encoders.Hex
import org.scalatest.funsuite.AnyFunSuite

/** BLAKE2b `F` compression — the primitive behind the EIP-152 `BLAKE2F` precompile.
  *
  * Known-answer vectors are the EIP-152 reference vectors (https://eips.ethereum.org/EIPS/eip-152), the same set used
  * by go-ethereum and besu. They exercise the malformed-length / bad-final-flag rejections ([[Blake2b.isValidInput]]
  * returning `None`), the `f = 0` vs `f = 1` final-block flag, and the round count parsed as a 32-bit big-endian word
  * (including the `0`-round and `1`-round edge cases).
  */
class Blake2bSpec extends AnyFunSuite:

  private def compressHex(input: String): Option[String] =
    Blake2b.compress(Hex.decode(input)).map(Hex.toHexString)

  // (input, expected) — expected == None means the input is rejected as malformed.
  private val vectors: Seq[(String, Option[String])] = Seq(
    // EIP-152 vector 1: input length 212 (one byte short) — rejected.
    "" -> None,
    // EIP-152 vector 2: input length 214 (one byte long) — rejected.
    "" -> None,
    // EIP-152 vector 3: final-block flag byte is 0x02 (neither 0 nor 1) — rejected.
    "" -> None,
    // EIP-152 vector 4: 0 rounds.
    "" ->
      Some(
        "08c9bcf367e6096a3ba7ca8485ae67bb2bf894fe72f36e3cf1361d5f3af54fa5d282e6ad7f520e511f6c3e2b8c68059b9442be0454267ce079217e1319cde05b"
      ),
    // EIP-152 vector 5: 12 rounds, final block (f = 1).
    "" ->
      Some(
        "ba80a53f981c4d0d6a2797b69f12f6e94c212f14685ac4b74b12bb6fdbffa2d17d87c5392aab792dc252d5de4533cc9518d38aa8dbf1925ab92386edd4009923"
      ),
    // EIP-152 vector 6: 12 rounds, not final block (f = 0).
    "" ->
      Some(
        "75ab69d3190a562c51aef8d88f1c2775876944407270c42c9844252c26d2875298743e7f6d5ea2f2d3e8d226039cd31b4e426ac4f2d3d666a610c2116fde4735"
      ),
    // EIP-152 vector 7: 1 round.
    "" ->
      Some(
        "b63a380cb2897d521994a85234ee2c181b5f844d2c624c002677e9703449d2fba551b3a8333bcdf5f2f7e08993d53923de3d64fcc68c034e717b9293fed7a421"
      )
  )

  test("compress matches all EIP-152 reference vectors"):
    vectors.foreach { case (input, expected) =>
      assert(compressHex(input) == expected, s"mismatch for input $input")
    }

  test("compress returns None for empty input"):
    assert(Blake2b.compress(Array.emptyByteArray).isEmpty)

  test("isValidInput requires exactly 213 bytes"):
    // 212 short, 214 long → invalid; 213 valid (final-flag byte defaults to 0x00).
    assert(
      !Blake2b.isValidInput(new Array[Byte](212)) &&
        !Blake2b.isValidInput(new Array[Byte](214)) &&
        Blake2b.isValidInput(new Array[Byte](213))
    )

  test("isValidInput rejects a final-flag byte other than 0x00 or 0x01"):
    def withFlag(flag: Byte): Array[Byte] =
      val a = new Array[Byte](213)
      a(212) = flag
      a
    assert(
      Blake2b.isValidInput(withFlag(0x01)) &&
        !Blake2b.isValidInput(withFlag(0x02)) &&
        !Blake2b.isValidInput(withFlag(0xff.toByte))
    )

  test("parseNumberOfRounds reads the big-endian 32-bit round count"):
    def withRounds(b0: Int, b1: Int, b2: Int, b3: Int): Array[Byte] =
      val a = new Array[Byte](213)
      a(0) = b0.toByte; a(1) = b1.toByte; a(2) = b2.toByte; a(3) = b3.toByte
      a
    assert(
      Blake2b.parseNumberOfRounds(withRounds(0x00, 0x00, 0x00, 0x0c)) == 12L &&
        Blake2b.parseNumberOfRounds(withRounds(0xff, 0xff, 0xff, 0xff)) == 0xffffffffL // unsigned
    )
